/**
 * SDK-hook call-site migration scan (client-sdk-codegen #05 rollout,
 * `.scratch/surgeon-audit-viability/tickets/08-...` in splicewire-app).
 *
 * A domain's `api.ts` sometimes still hand-writes a `useX` react-query wrapper for a route that the
 * codegen pipeline has since started emitting a generated hook for (same name, same route). This scans
 * for that exact shape and, when it's safe to swap, computes the {file, old, new} literal-rewrite edits
 * that retire the hand-written wrapper in favor of the generated one — surgeon's existing generic
 * `LiteralRewriteOperation`/`surgeon:rewrite` applies them; this module only diagnoses + computes spans.
 *
 * Pure over in-memory source maps (no fs) so it unit-tests without touching disk — mirrors
 * `blockdoc/lens.ts`'s split (parse/print over strings) and the PHP `SdkEndpointDriftAudit`'s
 * pure-core-over-collected-data shape. `recast` + `babel-ts`, not `@babel/traverse` — same reason as
 * `lens.ts`: a hand-rolled walker avoids pulling traverse in at runtime.
 *
 * **v2 — plain-string/template-literal call sites.** Not every call site wraps its path in
 * `route('name')`; many hand-write the literal path directly (`api.get('fragments', ...)`,
 * `` api.get(`fragments/${id}`) ``). `ui/src/generated/routes.ts` is a `name → path-template` map
 * already generated by the same `splicewire:beam:generate:client` command that emits the hooks
 * themselves, so no new PHP-side work is needed — {@see buildReverseRouteIndex} inverts it
 * (`path-template → name`) and {@see resolveRouteNameFromSegments} matches a call site's literal path
 * against it, segment by segment, treating `{param}` template segments as wildcards that must align
 * with a `${...}` interpolation (never with literal text sharing a segment).
 */

import * as recast from 'recast';
import * as babelTsParser from 'recast/parsers/babel-ts.js';
import * as t from '@babel/types';
import type { File } from '@babel/types';

const parser = babelTsParser;

/** A route-manifest entry — mirrors `RouteEntry`/`RouteMap` in `ui/src/lib/routes.ts`. */
export type RouteManifestEntry = string | { path: string; methods?: string[] };

/** The shape of `ui/src/generated/routes.ts`'s `defaults` export (or `adminDefaults`). */
export type RouteDefaults = Record<string, RouteManifestEntry>;

/** One inverted manifest entry: a path-template split into literal segments and `{param}` wildcards. */
export interface ReverseRouteEntry {
    routeName: string;
    /** `null` marks a `{param}` wildcard segment; a string is a literal segment that must match exactly. */
    segments: Array<string | null>;
    methods?: string[];
}

/** Sentinel embedded in a path-segment string to mark where a `${...}` interpolation sat. */
const INTERPOLATION_MARKER = '�INTERPOLATION�';

/**
 * Invert `ui/src/generated/routes.ts`'s `defaults` map (`name → path-template`) into
 * `path-template → name`, split into `/`-separated segments so a call site's literal path can be
 * matched positionally. `{fragment}`-style segments become wildcards ({@link ReverseRouteEntry.segments}
 * entries of `null`).
 */
export function buildReverseRouteIndex(routeDefaults: RouteDefaults): ReverseRouteEntry[] {
    return Object.entries(routeDefaults).map(([routeName, entry]) => {
        const path = typeof entry === 'string' ? entry : entry.path;
        const methods = typeof entry === 'string' ? undefined : entry.methods;
        const segments = path.split('/').map((seg) => (/^\{\w+\}$/.test(seg) ? null : seg));
        return { routeName, segments, methods };
    });
}

/**
 * Split a call site's raw path argument (a string literal or a template literal) into the same
 * `/`-separated segment shape {@link buildReverseRouteIndex} produces, so the two can be compared
 * positionally. A template literal's `${...}` interpolations become {@link INTERPOLATION_MARKER} —
 * only a segment that is *purely* an interpolation (no literal text sharing the segment) is treated as
 * a wildcard; a mixed segment (`` `fragments-${id}` ``) can't align with a manifest `{param}` segment
 * and returns `null` (unmatchable), rather than guessing.
 */
export function pathSegmentsFromNode(node: t.Expression): string[] | null {
    if (t.isStringLiteral(node)) {
        return node.value.split('/');
    }
    if (t.isTemplateLiteral(node)) {
        let combined = '';
        node.quasis.forEach((quasi, i) => {
            combined += quasi.value.cooked ?? quasi.value.raw;
            if (i < node.expressions.length) combined += INTERPOLATION_MARKER;
        });
        return combined.split('/');
    }
    return null;
}

/**
 * Resolve a call site's path segments (from {@link pathSegmentsFromNode}) to a route name via
 * {@link ReverseRouteEntry} lookup, matching segment-by-segment and — when the manifest entry carries
 * `methods` — narrowing by the call's HTTP verb to disambiguate routes sharing one path. Returns `null`
 * on no match OR an unresolved ambiguity (multiple routes fit); never guesses.
 */
export function resolveRouteNameFromSegments(segments: string[], verb: string, reverseIndex: ReverseRouteEntry[]): string | null {
    const verbUpper = verb.toUpperCase();
    const matches = reverseIndex.filter((entry) => {
        if (entry.segments.length !== segments.length) return false;
        const segmentsMatch = entry.segments.every((templateSeg, i) => {
            const argSeg = segments[i];
            return templateSeg === null ? argSeg === INTERPOLATION_MARKER : templateSeg === argSeg;
        });
        if (!segmentsMatch) return false;
        return !entry.methods || entry.methods.length === 0 || entry.methods.some((m) => m.toUpperCase() === verbUpper);
    });

    return matches.length === 1 ? matches[0].routeName : null;
}

/**
 * Extract a {@link RouteDefaults} object straight from `ui/src/generated/routes.ts`'s source text —
 * pulls the `export const defaults: RouteMap = {...}` (or `adminDefaults`) object literal's static
 * value via the AST. Safe to evaluate structurally rather than `import`ing: the file is auto-generated,
 * so every entry is a plain string or `{ path, methods }` object literal, never a computed value — this
 * lets the CLI load it without a TypeScript loader/register step.
 */
export function extractRouteDefaultsFromSource(source: string, exportName: string = 'defaults'): RouteDefaults {
    const ast = parseSource(source);
    for (const stmt of ast.program.body) {
        if (!t.isExportNamedDeclaration(stmt) || !stmt.declaration || !t.isVariableDeclaration(stmt.declaration)) continue;
        for (const decl of stmt.declaration.declarations) {
            if (!t.isIdentifier(decl.id) || decl.id.name !== exportName) continue;
            if (!decl.init || !t.isObjectExpression(decl.init)) continue;
            return objectExpressionToRouteDefaults(decl.init);
        }
    }
    return {};
}

function objectExpressionToRouteDefaults(obj: t.ObjectExpression): RouteDefaults {
    const result: RouteDefaults = {};
    for (const prop of obj.properties) {
        if (!t.isObjectProperty(prop)) continue;
        const key = t.isStringLiteral(prop.key) ? prop.key.value : t.isIdentifier(prop.key) ? prop.key.name : null;
        if (key === null) continue;

        if (t.isStringLiteral(prop.value)) {
            result[key] = prop.value.value;
            continue;
        }
        if (!t.isObjectExpression(prop.value)) continue;

        const pathProp = findProp(prop.value, 'path');
        if (!pathProp || !t.isStringLiteral(pathProp.value)) continue;
        const methodsProp = findProp(prop.value, 'methods');
        const methods =
            methodsProp && t.isArrayExpression(methodsProp.value)
                ? methodsProp.value.elements
                      .filter((e): e is t.StringLiteral => !!e && t.isStringLiteral(e))
                      .map((e) => e.value)
                : undefined;
        result[key] = methods ? { path: pathProp.value.value, methods } : { path: pathProp.value.value };
    }
    return result;
}

export interface QueryWrapper {
    functionName: string;
    routeName: string;
    httpVerb: string;
    safe: boolean;
    unsafeReason?: string;
    start: number;
    end: number;
}

export interface HookIndexEntry {
    functionName: string;
    routeName: string;
    hookModule: string;
}

export interface EditEntry {
    file: string;
    old: string;
    new: string;
}

export interface MigrationCandidate {
    functionName: string;
    routeName: string;
    apiFile: string;
    hookModule: string;
    edits: EditEntry[];
}

export interface MigrationException {
    functionName: string;
    routeName: string;
    apiFile: string;
    reason: string;
}

export interface ScanReport {
    candidates: MigrationCandidate[];
    exceptions: MigrationException[];
}

/** A path → source-text map — the in-memory filesystem stand-in every pure function here operates over. */
export type FileMap = Record<string, string>;

function parseSource(source: string): File {
    return recast.parse(source, { parser }) as File;
}

/**
 * Every top-level `export function useX(...) { return useQuery({ queryKey: ['route.name', ...], queryFn:
 * async () => { ... api.<verb>(route('route.name', ...)) ... } }); }` wrapper in a module — the shape
 * both a hand-written domain `api.ts` AND a generated `generated/hooks/*.ts` file share, so this one
 * extractor indexes both sides.
 */
export function findQueryWrappers(source: string, reverseIndex: ReverseRouteEntry[] = []): QueryWrapper[] {
    const ast = parseSource(source);
    const wrappers: QueryWrapper[] = [];

    for (const stmt of ast.program.body) {
        const decl = t.isExportNamedDeclaration(stmt) && stmt.declaration && t.isFunctionDeclaration(stmt.declaration)
            ? stmt.declaration
            : t.isFunctionDeclaration(stmt)
              ? stmt
              : null;
        if (!decl || !decl.id) continue;

        const wrapper = extractWrapper(decl, stmt, reverseIndex);
        if (wrapper) wrappers.push(wrapper);
    }

    return wrappers;
}

function extractWrapper(fn: t.FunctionDeclaration, outer: t.Statement, reverseIndex: ReverseRouteEntry[]): QueryWrapper | null {
    if (!fn.body) return null;
    const returnStmt = fn.body.body.find((s): s is t.ReturnStatement => t.isReturnStatement(s));
    if (!returnStmt || !returnStmt.argument || !t.isCallExpression(returnStmt.argument)) return null;

    const call = returnStmt.argument;
    if (!t.isIdentifier(call.callee) || call.callee.name !== 'useQuery') return null;
    const [arg] = call.arguments;
    if (!arg || !t.isObjectExpression(arg)) return null;

    // `queryKey` just has to exist to recognize the wrapper shape — its content isn't the route-name
    // source of truth (v1 required `queryKey[0]` to literally be the route name, which only held for
    // the `route('name')`-wrapped shape; a plain-string-path call site's queryKey is descriptive, not
    // necessarily the dotted route name — see `useFragments`'s `['fragments', query]`).
    const queryKeyProp = findProp(arg, 'queryKey');
    if (!queryKeyProp || !t.isArrayExpression(queryKeyProp.value)) return null;

    const queryFnProp = findProp(arg, 'queryFn');
    if (!queryFnProp) return null;
    const fnNode = queryFnProp.value;
    if (!t.isArrowFunctionExpression(fnNode) && !t.isFunctionExpression(fnNode)) return null;

    const apiCall = findApiCall(fnNode, reverseIndex);
    if (!apiCall || !apiCall.routeName) return null;

    const safe = apiCall.verb === 'get' && !apiCall.extraArgs;
    const unsafeReason = safe
        ? undefined
        : apiCall.verb !== 'get'
          ? `api.${apiCall.verb}(...) is not a GET — not hook-migratable`
          : 'queryFn passes extra request config beyond the path argument — possible query-string filtering, needs manual review';

    return {
        functionName: fn.id!.name,
        routeName: apiCall.routeName,
        httpVerb: apiCall.verb,
        safe,
        unsafeReason,
        start: outer.start ?? fn.start!,
        end: outer.end ?? fn.end!,
    };
}

function findProp(obj: t.ObjectExpression, name: string): t.ObjectProperty | null {
    for (const p of obj.properties) {
        if (
            t.isObjectProperty(p) &&
            ((t.isIdentifier(p.key) && p.key.name === name) || (t.isStringLiteral(p.key) && p.key.value === name))
        ) {
            return p;
        }
    }
    return null;
}

interface ApiCallShape {
    verb: string;
    routeName: string | null;
    extraArgs: boolean;
}

/**
 * Find the (first) `api.<verb>(<path>, ...)` call inside a queryFn body whose path argument resolves to
 * a route name — either `route('name')` (v1 shape) or a plain string/template-literal path matched
 * against `reverseIndex` (v2 shape, see {@link resolveRouteNameFromSegments}). A call whose path doesn't
 * resolve is skipped (not treated as a match failure) so the walk can keep looking — mirrors v1's
 * behavior of ignoring non-`route(...)` calls rather than aborting the scan.
 */
function findApiCall(fnNode: t.ArrowFunctionExpression | t.FunctionExpression, reverseIndex: ReverseRouteEntry[]): ApiCallShape | null {
    let result: ApiCallShape | null = null;
    walk(fnNode.body, (node) => {
        if (result) return;
        if (!t.isCallExpression(node) || !t.isMemberExpression(node.callee)) return;
        const { object, property } = node.callee;
        if (!t.isIdentifier(object) || object.name !== 'api' || !t.isIdentifier(property)) return;

        const [routeArg, ...rest] = node.arguments;
        if (!routeArg) return;

        let routeName: string | null = null;
        if (t.isCallExpression(routeArg) && t.isIdentifier(routeArg.callee) && routeArg.callee.name === 'route') {
            const [routeNameArg] = routeArg.arguments;
            routeName = routeNameArg && t.isStringLiteral(routeNameArg) ? routeNameArg.value : null;
        } else if (t.isStringLiteral(routeArg) || t.isTemplateLiteral(routeArg)) {
            const segments = pathSegmentsFromNode(routeArg);
            routeName = segments ? resolveRouteNameFromSegments(segments, property.name, reverseIndex) : null;
        }
        if (!routeName) return;

        result = { verb: property.name, routeName, extraArgs: rest.length > 0 };
    });
    return result;
}

/** Depth-first walk of an AST subtree, visiting every node (mirrors blockdoc/lens.ts — no @babel/traverse). */
function walk(node: unknown, visit: (n: t.Node) => void): void {
    if (!node || typeof node !== 'object') return;
    if (Array.isArray(node)) {
        for (const item of node) walk(item, visit);
        return;
    }
    const n = node as t.Node;
    if (typeof (n as { type?: unknown }).type === 'string') visit(n);
    for (const key of Object.keys(node)) {
        if (key === 'loc' || key === 'start' || key === 'end' || key === 'range') continue;
        if (key === 'tokens' || key === 'comments' || key === 'original') continue;
        walk((node as Record<string, unknown>)[key], visit);
    }
}

/** Index every generated hook file's exported `useX` wrappers by (functionName, routeName). */
export function buildHookIndex(hookFiles: FileMap, reverseIndex: ReverseRouteEntry[] = []): HookIndexEntry[] {
    const index: HookIndexEntry[] = [];
    for (const [path, source] of Object.entries(hookFiles)) {
        const hookModule = basenameNoExt(path);
        for (const w of findQueryWrappers(source, reverseIndex)) {
            index.push({ functionName: w.functionName, routeName: w.routeName, hookModule });
        }
    }
    return index;
}

function basenameNoExt(path: string): string {
    const base = path.split('/').pop() ?? path;
    return base.replace(/\.[^.]+$/, '');
}

interface ImportSite {
    start: number;
    end: number;
    specifiers: string[];
    onlyThisName: boolean;
}

/**
 * The import statement in `source` that imports `functionName` from one of `moduleCandidates` (a
 * consumer's relative-specifier resolution of the api module), or null if this file doesn't import it
 * from there.
 */
export function findImportSite(source: string, functionName: string, moduleCandidates: string[]): ImportSite | null {
    const ast = parseSource(source);
    for (const stmt of ast.program.body) {
        if (!t.isImportDeclaration(stmt)) continue;
        if (!moduleCandidates.includes(stmt.source.value)) continue;

        const names = stmt.specifiers
            .filter((s): s is t.ImportSpecifier => t.isImportSpecifier(s))
            .map((s) => (t.isIdentifier(s.imported) ? s.imported.name : s.imported.value));
        if (!names.includes(functionName)) continue;

        return {
            start: stmt.start!,
            end: stmt.end!,
            specifiers: names,
            onlyThisName: names.length === 1,
        };
    }
    return null;
}

/** The relative import specifier a file at `fromFile` would use to import `toFile` (no extension). */
export function importSpecifierFor(fromFile: string, toFile: string): string {
    const fromDir = fromFile.split('/').slice(0, -1).join('/');
    const rel = relativePosixPath(fromDir, toFile).replace(/\.tsx?$/, '');
    return rel.startsWith('.') ? rel : `./${rel}`;
}

/** POSIX-style relative path from `fromDir` to `toFile` — both absolute, `/`-separated. */
function relativePosixPath(fromDir: string, toFile: string): string {
    const fromParts = fromDir.split('/').filter(Boolean);
    const toParts = toFile.split('/').filter(Boolean);
    let i = 0;
    while (i < fromParts.length && i < toParts.length && fromParts[i] === toParts[i]) i++;
    const up = fromParts.length - i;
    const down = toParts.slice(i);
    return [...Array(up).fill('..'), ...down].join('/');
}

/**
 * Scan `apiFiles` (the domain `api.ts` files a wrapper may live in) for hand-written `useX` wrappers
 * that a `hookFiles` entry already covers, then search `importerSearchFiles` (a superset — every source
 * file that could plausibly import the wrapper, not just the scoped domain) for the sites that need
 * their import specifier repointed. A wrapper only becomes a `MigrationCandidate` when EVERY importer
 * found resolves cleanly (a single, unbundled `{ useX }` import) — a bundled or unresolved importer
 * downgrades the whole wrapper to an exception rather than emitting a partial, build-breaking edit set.
 *
 * `routeDefaults` is `ui/src/generated/routes.ts`'s `defaults` export (or equivalent) — optional
 * because the v1 `route('name')` shape doesn't need it; passing it in additionally recognizes call
 * sites that hand-write their path as a string/template literal instead (see module docblock).
 */
export function scan(hookFiles: FileMap, apiFiles: FileMap, importerSearchFiles: FileMap, routeDefaults: RouteDefaults = {}): ScanReport {
    const reverseIndex = buildReverseRouteIndex(routeDefaults);
    const hookIndex = buildHookIndex(hookFiles, reverseIndex);
    const candidates: MigrationCandidate[] = [];
    const exceptions: MigrationException[] = [];

    for (const [apiFile, source] of Object.entries(apiFiles)) {
        for (const wrapper of findQueryWrappers(source, reverseIndex)) {
            const hookMatch = hookIndex.find((h) => h.functionName === wrapper.functionName && h.routeName === wrapper.routeName);
            if (!hookMatch) continue; // no generated hook covers this route (yet) — growing coverage is a separate operation

            if (!wrapper.safe) {
                exceptions.push({ functionName: wrapper.functionName, routeName: wrapper.routeName, apiFile, reason: wrapper.unsafeReason! });
                continue;
            }

            const edits: EditEntry[] = [{ file: apiFile, old: source.slice(wrapper.start, wrapper.end), new: '' }];
            let blocked = false;

            for (const [consumerFile, consumerSource] of Object.entries(importerSearchFiles)) {
                if (consumerFile === apiFile) continue;
                const spec = importSpecifierFor(consumerFile, apiFile);
                const site = findImportSite(consumerSource, wrapper.functionName, [spec, `${spec}.ts`, `${spec}.tsx`]);
                if (!site) continue;

                if (!site.onlyThisName) {
                    exceptions.push({
                        functionName: wrapper.functionName,
                        routeName: wrapper.routeName,
                        apiFile,
                        reason: `${consumerFile} imports ${wrapper.functionName} bundled with other names (${site.specifiers.join(', ')}) — split the import manually first`,
                    });
                    blocked = true;
                    continue;
                }

                edits.push({
                    file: consumerFile,
                    old: consumerSource.slice(site.start, site.end),
                    new: `import { ${wrapper.functionName} } from '@/generated/hooks/${hookMatch.hookModule}';`,
                });
            }

            if (blocked) continue;
            candidates.push({ functionName: wrapper.functionName, routeName: wrapper.routeName, apiFile, hookModule: hookMatch.hookModule, edits });
        }
    }

    return { candidates, exceptions };
}

